import{_ as n,a0 as a,w as r,s as i,ao as u,I as p,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Shotwell 0.15发布了!添加了更多新功能及修复! | LCTT x X-CMD","titleTemplate":false,"description":"Shotwell 0.15发布了!添加了更多新功能及修复! | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Shotwell 0.15发布了!添加了更多新功能及修复! | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Shotwell 0.15发布了!添加了更多新功能及修复! | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Shotwell 0.15 released with new features and fixes","title":"Shotwell 0.15发布了!添加了更多新功能及修复!","tag":"201310","desc":""},"relativePath":"201310/Shotwell 0.15 released with new features and fixes.md","filePath":"[post].md"}'),d={name:"201310/Shotwell 0.15 released with new features and fixes.md"};function h(w,t,f,m,g,S){const l=a("Link");return r(),i("div",null,[t[11]||(t[11]=u(`<h1 id="shotwell-0-15发布了-添加了更多新功能及修复" tabindex="-1">Shotwell 0.15发布了!添加了更多新功能及修复! <a class="header-anchor" href="#shotwell-0-15发布了-添加了更多新功能及修复" aria-label="Permalink to “Shotwell 0.15发布了!添加了更多新功能及修复!”">​</a></h1><p>Ubuntu 默认安装了Shotwell，它能轻松的管理图片，提供基本的图库管理和图片编辑功能，以后将提供更多有用的功能.</p><p>Shotwell 已经更新到0.15版本，带来了新的特征，修复了大量已知的bug，并进行了更多的优化。</p><p><code>右击图片--&gt;打开方式--&gt;Shotwell图片编辑</code>，用Shotwell打开图片后，在下边有几个选项，其中包括Adjust(调整)选项。</p><p>点击<code>Adjust</code>按钮，用户能清楚的发现最新的Highlights(高亮)条目,这对于微调高亮很有帮助；举例来说，将&#39;Highlights&#39;设置调到很低，这样就能降低正在编辑的图片的明暗程度。</p><p><img src="http://iloveubuntu.net/pictures_me/Shotwell%20015%20adjust.jpg" alt=""></p><p>点击按钮条中的<code>Crop</code>按钮，弹出可更改大小的会话框，允许用户根据要求自定义大小裁剪图片，0.15版本的对话框增加了 <strong>尺寸显示</strong> 的功能。</p><p>改变会话框的大小，会实时的显示目前的尺寸大小，用户能自由随意观察修剪框中的尺寸；举个例子，为了得到一张640<em>480的图片，用户可以将裁剪框调整到640</em>480，在图片编辑器中便利地增添图片清晰度。</p><p><img src="http://iloveubuntu.net/pictures_me/Shotwell%20015%20resize%20values.jpg" alt=""></p><p>除此以外,Shotwell 0.15 还增添了:</p><ul><li><p>支持Youtube插件 OAuth/OpenID 认证</p></li><li><p>增强视频文件的再次导入</p></li><li><p>优化了视频的缩略图生成</p></li><li><p>修复了很多漏洞</p></li></ul><p>我们怎么<strong>安装</strong> Shotwell 0.15呢?</p><p>添加以下 <strong>官方</strong> PPA(Ubuntu 12.10, Ubuntu 13.04)</p><pre><code>sudo add-apt-repository ppa:yorba/ppa 

sudo apt-get update
sudo apt-get install shotwell
</code></pre><p>Shotwell 0.15已经被放入了Ubuntu 13.10，你只需要定期的更新软件，便会帮你自动安装,享受它带给你的乐趣吧!</p><hr>`,16)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(l,{href:"http://iloveubuntu.net/shotwell-015-released-new-features-and-fixes"},{default:s(()=>[...t[0]||(t[0]=[e("http://iloveubuntu.net/shotwell-015-released-new-features-and-fixes",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原创翻译，",-1)),o(l,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[e("Linux中国",-1)])]),_:1}),t[6]||(t[6]=e(" 荣誉推出",-1))]),p("p",null,[t[9]||(t[9]=e("译者：",-1)),o(l,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[7]||(t[7]=[e("Luoxcat",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),o(l,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[8]||(t[8]=[e("caroline",-1)])]),_:1})])])}const b=n(d,[["render",h]]);export{C as __pageData,b as default};
